import React, { useState } from 'react';
import { Button } from './components/ui/button';
import { Card, CardContent } from './components/ui/card';
import { motion } from 'framer-motion';

export default function FoodDonationApp() {
  const [userType, setUserType] = useState(null);
  const [donations, setDonations] = useState([]);
  const [newDonation, setNewDonation] = useState({ item: '', quantity: '' });

  const foodItems = [
    'Bread', 'Rice', 'Pasta', 'Vegetables', 'Fruits', 'Dairy Products', 'Meat', 'Seafood', 'Snacks', 'Beverages'
  ];

  const quantityOptions = {
    'Bread': ['1 loaf', '2 loaves', '5 loaves'],
    'Rice': ['1 kg', '2 kg', '5 kg'],
    'Pasta': ['500 g', '1 kg', '2 kg'],
    'Vegetables': ['1 kg', '2 kg', '5 kg'],
    'Fruits': ['1 kg', '2 kg', '5 kg'],
    'Dairy Products': ['1 liter', '2 liters', '5 liters'],
    'Meat': ['500 g', '1 kg', '2 kg'],
    'Seafood': ['500 g', '1 kg', '2 kg'],
    'Snacks': ['10 packs', '20 packs', '50 packs'],
    'Beverages': ['1 bottle', '2 bottles', '5 bottles']
  };

  const handleDonationSubmit = () => {
    if (newDonation.item && newDonation.quantity) {
      setDonations([...donations, newDonation]);
      setNewDonation({ item: '', quantity: '' });
    }
  };

  const handleClaimDonation = (index) => {
    const updatedDonations = donations.filter((_, i) => i !== index);
    setDonations(updatedDonations);
  };

  if (!userType) {
    return (
      <motion.div 
        initial={{ opacity: 0 }} 
        animate={{ opacity: 1 }} 
        className="flex flex-col items-center justify-center min-h-screen bg-gradient-to-r from-green-300 to-blue-300 p-6">
        <h1 className="text-4xl font-extrabold text-white mb-6 drop-shadow-lg">Welcome to Food Donation App</h1>
        <div className="space-x-4">
          <Button onClick={() => setUserType('donor')} className="px-6 py-3 text-lg bg-white text-green-600 rounded-2xl shadow-lg hover:bg-green-100">Login as Donor</Button>
          <Button onClick={() => setUserType('ngo')} className="px-6 py-3 text-lg bg-white text-blue-600 rounded-2xl shadow-lg hover:bg-blue-100">Login as NGO</Button>
        </div>
      </motion.div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <motion.h1 
        initial={{ x: -100, opacity: 0 }} 
        animate={{ x: 0, opacity: 1 }} 
        transition={{ duration: 0.5 }}
        className="text-3xl font-bold text-center mb-6 text-gray-800">
        {userType === 'donor' ? 'Post a Donation' : 'Available Donations'}
      </motion.h1>

      {userType === 'donor' ? (
        <motion.div 
          initial={{ y: 20, opacity: 0 }} 
          animate={{ y: 0, opacity: 1 }} 
          transition={{ delay: 0.2 }}
          className="max-w-md mx-auto bg-white p-6 rounded-2xl shadow-xl">
          <select
            value={newDonation.item}
            onChange={(e) => setNewDonation({ ...newDonation, item: e.target.value, quantity: '' })}
            className="border p-3 rounded-xl mb-4 w-full text-gray-700 bg-gray-100"
          >
            <option value="">Select Food Item</option>
            {foodItems.map((item, index) => (
              <option key={index} value={item}>{item}</option>
            ))}
          </select>

          {newDonation.item && (
            <select
              value={newDonation.quantity}
              onChange={(e) => setNewDonation({ ...newDonation, quantity: e.target.value })}
              className="border p-3 rounded-xl mb-4 w-full text-gray-700 bg-gray-100"
            >
              <option value="">Select Quantity</option>
              {quantityOptions[newDonation.item].map((qty, index) => (
                <option key={index} value={qty}>{qty}</option>
              ))}
            </select>
          )}

          <Button onClick={handleDonationSubmit} className="w-full bg-green-500 text-white py-2 rounded-xl shadow-md hover:bg-green-600">Submit Donation</Button>
        </motion.div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {donations.length > 0 ? (
            donations.map((donation, index) => (
              <motion.div 
                key={index} 
                initial={{ scale: 0.9, opacity: 0 }} 
                animate={{ scale: 1, opacity: 1 }} 
                transition={{ delay: index * 0.1 }}
              >
                <Card className="bg-white p-4 rounded-2xl shadow-lg hover:shadow-xl">
                  <CardContent>
                    <h2 className="text-xl font-semibold text-gray-800">{donation.item}</h2>
                    <p className="text-gray-600">Quantity: {donation.quantity}</p>
                    <Button onClick={() => handleClaimDonation(index)} className="mt-4 w-full bg-blue-500 text-white py-2 rounded-xl hover:bg-blue-600">Claim Donation</Button>
                  </CardContent>
                </Card>
              </motion.div>
            ))
          ) : (
            <p className="text-center text-gray-500">No donations available at the moment.</p>
          )}
        </div>
      )}

      <Button onClick={() => setUserType(null)} className="mt-8 block mx-auto bg-red-500 text-white py-2 px-6 rounded-xl hover:bg-red-600">Logout</Button>
    </div>
  );
}
